float4 frag(UPEInput i)
{
    float u = i.uv.x;
    float v = i.uv.y;
    float head = i.custom.x;
    float life = 1.0 - i.color.a;
    float eat = saturate((life - _Eat) / max(1.0 - _Eat, 0.001));
    float tailS = max(head - _Tail, eat * 1.02);
    float k = saturate((u - tailS) / max(head - tailS, 0.001));
    float m = smoothstep(0.0, 0.08, k) * (1.0 - smoothstep(head, head + 0.015, u)) * step(tailS, u);
    float tipT = 1.0 - smoothstep(0.78, 1.0, u / max(head, 0.001));
    float spread = _Spread * (0.3 + 0.7 * k) * (0.2 + 0.8 * tipT);
    float dv = abs(v - 0.5);
    float prof = exp(-dv * dv / max(spread * spread, 0.0001) * 2.0);
    float core = exp(-dv * dv / max(spread * spread * 0.04, 0.00001) * 2.0);
    float fib = 0.55 + 0.45 * vnoise(float2(u * _Fiber - i.time * _Scroll, v * 6.0));
    float er = vnoise(float2(u * 14.0, v * 5.0 - i.time));
    float erodeM = saturate((er + 0.55 - life * 1.1) * 5.0);
    float fadeAll = 1.0 - smoothstep(0.55, 1.0, life);
    float3 col = (_Glow.rgb * prof * fib + _Core.rgb * core) * pow(k, 1.6) * m * erodeM * fadeAll * i.color.rgb;
    return float4(col, 1.0);
}
